import { z } from "zod";

/**
 * Clinical-domain schemas.
 *
 * Schemas that are sent to OpenAI as structured-output targets (ClinicalFacts,
 * RiskFlag) intentionally use `.nullable()` rather than `.optional()`, because
 * OpenAI strict structured outputs require every property to be present.
 * `PatientContext` is supplied by us (a fixture / lookup), never generated by
 * the model, so it can be shaped freely.
 */

/** Context about the patient, provided to the workflow (not model-generated). */
export const PatientContextSchema = z.object({
  patientId: z.string(),
  name: z.string(),
  dateOfBirth: z.string(),
  age: z.number().int(),
  sex: z.enum(["male", "female", "other", "unknown"]),
  primaryDiagnoses: z.array(z.string()),
  allergies: z.array(z.string()),
  careSetting: z.string(),
  episodeSummary: z.string(),
});
export type PatientContext = z.infer<typeof PatientContextSchema>;

/** A risk flag surfaced from the clinical content. */
export const RiskFlagSchema = z.object({
  category: z.enum([
    "clinical",
    "safety",
    "medication",
    "functional",
    "other",
  ]),
  severity: z.enum(["low", "medium", "high"]),
  description: z.string(),
});
export type RiskFlag = z.infer<typeof RiskFlagSchema>;

const VitalsSchema = z.object({
  bloodPressure: z.string().nullable(),
  heartRate: z.number().nullable(),
  respiratoryRate: z.number().nullable(),
  temperatureF: z.number().nullable(),
  oxygenSaturation: z.number().nullable(),
  weightLbs: z.number().nullable(),
  painScore: z.number().nullable(),
});

const DiagnosisSchema = z.object({
  description: z.string(),
  icd10: z.string().nullable(),
});

const MedicationSchema = z.object({
  name: z.string(),
  dosage: z.string(),
  frequency: z.string(),
  adherenceConfirmed: z.boolean(),
});

/** Structured clinical facts extracted from a visit transcript (model output). */
export const ClinicalFactsSchema = z.object({
  visitType: z.string(),
  vitals: VitalsSchema,
  diagnoses: z.array(DiagnosisSchema),
  medications: z.array(MedicationSchema),
  functionalStatus: z.array(z.string()),
  interventions: z.array(z.string()),
  carePlan: z.array(z.string()),
  riskFlags: z.array(RiskFlagSchema),
});
export type ClinicalFacts = z.infer<typeof ClinicalFactsSchema>;
